// Checks that the request really came from Convex before anything else runs.
// The signature covers the exact bytes Convex sent (the raw body, not a
// re-serialised copy) plus the timestamp, and old timestamps are refused so a
// captured request cannot be replayed later.
const crypto = require('crypto');

const MAX_SKEW_SECONDS = 300;
const EVENTS = ['loan.requested', 'loan.approved', 'loan.declined', 'loan.returned'];

const secret = $env.LENDLOOP_HMAC_SECRET;
if (!secret || secret.length < 32) {
  // A configuration problem, not a bad request: fail the execution so the
  // error workflow reports it and Convex retries later.
  throw new Error('LENDLOOP_HMAC_SECRET is missing or shorter than 32 characters in the n8n container.');
}

const reject = (reason) => [{ json: { valid: false, reason } }];

const headers = $input.first().json.headers ?? {};
const timestamp = headers['x-lendloop-timestamp'];
const signature = headers['x-lendloop-signature'];
if (typeof timestamp !== 'string' || typeof signature !== 'string') return reject('missing_headers');
if (!/^\d{1,12}$/.test(timestamp) || !/^[0-9a-f]{64}$/.test(signature)) return reject('bad_signature');
if (Math.abs(Date.now() / 1000 - Number(timestamp)) > MAX_SKEW_SECONDS) return reject('expired');

const rawBody = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
const expected = crypto.createHmac('sha256', secret).update(`${timestamp}.${rawBody}`).digest();
if (!crypto.timingSafeEqual(expected, Buffer.from(signature, 'hex'))) return reject('bad_signature');

// Signed by Convex, but still check the shape before using it.
let payload;
try {
  payload = JSON.parse(rawBody);
} catch {
  return reject('invalid_json');
}
const { eventId, event, loan, recipient } = payload ?? {};
const isText = (value) => typeof value === 'string' && value.length > 0 && value.length <= 200;
if (
  !isText(eventId) || !EVENTS.includes(event) ||
  !isText(loan?.toolName) || !isText(loan?.startDate) || !isText(loan?.endDate) ||
  !isText(recipient?.name) || !isText(recipient?.email)
) {
  return reject('invalid_payload');
}

// Convex retries if it never saw our 200 (timeout, restart). Remember which
// events were already emailed so a retry does not email the person twice.
const sent = $getWorkflowStaticData('global').sentEventIds ?? {};
return [{ json: { valid: true, duplicate: Boolean(sent[eventId]), payload } }];

// One short plain-text email. Only the fields Convex sent are available here:
// recipient name and email, tool name, dates and the event.
const { event, loan, recipient } = $input.first().json.payload;
const appUrl = $env.LENDLOOP_APP_URL || 'http://localhost:3000';
const dates = loan.startDate === loan.endDate ? loan.startDate : `${loan.startDate} to ${loan.endDate}`;

const messages = {
  'loan.requested': {
    subject: `New request to borrow your ${loan.toolName}`,
    body: `Someone would like to borrow your ${loan.toolName} (${dates}).\nApprove or decline it here: ${appUrl}/incoming`,
  },
  'loan.approved': {
    subject: `Approved: ${loan.toolName}`,
    body: `Your request to borrow the ${loan.toolName} (${dates}) was approved.\nDetails: ${appUrl}/requests`,
  },
  'loan.declined': {
    subject: `Declined: ${loan.toolName}`,
    body: `Your request to borrow the ${loan.toolName} (${dates}) was declined.\nOther tools: ${appUrl}/tools`,
  },
  'loan.returned': {
    subject: `Returned: ${loan.toolName}`,
    body: `The ${loan.toolName} (${dates}) has been marked as returned. Thanks for bringing it back.`,
  },
};

const { subject, body } = messages[event];
return [{
  json: {
    to: recipient.email,
    subject,
    text: `Hi ${recipient.name},\n\n${body}\n\nLendLoop`,
  },
}];

// Record the event as emailed (see "Verify signature"), keeping 14 days of ids.
const KEEP_MS = 14 * 24 * 60 * 60 * 1000;
const { eventId } = $('Verify signature').first().json.payload;

const staticData = $getWorkflowStaticData('global');
const sent = staticData.sentEventIds ?? {};
const now = Date.now();
for (const [id, at] of Object.entries(sent)) {
  if (now - at > KEEP_MS) delete sent[id];
}
sent[eventId] = now;
staticData.sentEventIds = sent;

return [{ json: { eventId } }];
